import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

function generateSchemaSource(json:unknown){
    return `
/*Auto generated by script. DO NOT EDIT*/

export const gatewaySchema = ${JSON.stringify(json, null, 4)} as const;

export type GatewaySchema = typeof gatewaySchema;
    `
}
function main(){
    const input = "library/Gateway/Gateway.json"
    const output = "library/Gateway/Gateway.schema.ts"
    const source = generateSchemaSource(JSON.parse(readFileSync(resolve(input), "utf8")))
    mkdirSync(dirname(resolve(output)), { recursive: true });
    writeFileSync(resolve(output), source);
    console.log(`Generated ${output}`);
}

main()